    reg v1, v2, v3;
    reg signed [12:0] d1, d2, d3;
    reg signed [7:0] x_prev1, x_prev2, x_prev3;

    wire r3 = !v3 || out_ready;
    wire r2 = !v2 || r3;
    wire r1 = !v1 || r2;

